assistantMessageEvent.delta:
cd "$(pwd)" && node --input-type=module -e "
import { uniqueStrings } from './unique_repeat.mjs';

// Basic dedup preserving order
const a = ['apple', 'banana', 'apple', 'cherry', 'banana'];
console.log('basic:', JSON.stringify(uniqueStrings(a)));

// Case sensitivity
const b = ['Apple', 'apple', 'APPLE', 'apple'];
console.log('case:', JSON.stringify(uniqueStrings(b)));

// Whitespace not trimmed
const c = ['  x', 'x', '  x', 'x  '];
console.log('whitespace:', JSON.stringify(uniqueStrings(c)));

// Input not mutated
const d = ['a', 'b', 'a', 'c'];
const copy = [...d];
uniqueStrings(d);
console.log('not mutated:', JSON.stringify(d) === JSON.stringify(copy));

// Empty input
console.log('empty:', JSON.stringify(uniqueStrings([])));

// Single element
console.log('single:', JSON.stringify(uniqueStrings(['only'])));
"

